public class RegulatoryRequirementEngineTests {
  [Fact] public async Task Matching_verified_rule_applies_and_uses_operation_date(){await using var f=await RegulatoryFixture.Create(tariff:"8504.40.01",date:new(2026,3,1));f.Rule("R-1",RegulatoryRequirementStatus.VERIFIED,DocumentFieldCodes.TariffFraction,RegulatoryConditionOperator.EQUALS,"85044001",from:new(2026,1,1));await f.Save();var r=Assert.Single(await f.Evaluate());Assert.Equal(RegulatoryApplicabilityOutcome.APPLIES,r.AutomatedOutcome);Assert.Equal(new DateTime(2026,3,1),r.EvaluationDate);Assert.Contains("Resultado LEGAL: No evaluado",r.Explanation);}
  [Fact] public async Task Nonmatching_rule_does_not_apply_and_requires_no_evidence(){await using var f=await RegulatoryFixture.Create(tariff:"99999999");f.Rule("R-1",RegulatoryRequirementStatus.VERIFIED,DocumentFieldCodes.TariffFraction,RegulatoryConditionOperator.EQUALS,"85044001",evidence:"PERMISO_PREVIO");await f.Save();var r=Assert.Single(await f.Evaluate());Assert.Equal(RegulatoryApplicabilityOutcome.DOES_NOT_APPLY,r.AutomatedOutcome);Assert.Equal(RegulatoryEvidenceStatus.NOT_REQUIRED,r.EvidenceStatus);Assert.Empty(r.Evidence);}
  [Fact] public async Task Missing_value_is_insufficient_data(){await using var f=await RegulatoryFixture.Create();f.Rule("R-1",RegulatoryRequirementStatus.VERIFIED,DocumentFieldCodes.Nico,RegulatoryConditionOperator.EQUALS,"01");await f.Save();var r=Assert.Single(await f.Evaluate());Assert.Equal(RegulatoryApplicabilityOutcome.INSUFFICIENT_DATA,r.AutomatedOutcome);Assert.Equal(RegulatoryEvidenceStatus.INSUFFICIENT_DATA,r.EvidenceStatus);}
  [Fact] public async Task Draft_rule_never_produces_definitive_outcome(){await using var f=await RegulatoryFixture.Create(tariff:"85044001");f.Rule("R-1",RegulatoryRequirementStatus.DRAFT,DocumentFieldCodes.TariffFraction,RegulatoryConditionOperator.EQUALS,"85044001");await f.Save();var r=Assert.Single(await f.Evaluate());Assert.Equal(RegulatoryApplicabilityOutcome.MANUAL_REVIEW,r.AutomatedOutcome);Assert.True(r.ManualReviewRequired);}
  [Fact] public async Task Description_partial_contains_is_manual_not_definitive(){await using var f=await RegulatoryFixture.Create(description:"Equipo médico especial");f.Rule("R-1",RegulatoryRequirementStatus.VERIFIED,DocumentFieldCodes.Description,RegulatoryConditionOperator.CONTAINS_NORMALIZED,"médico");await f.Save();var r=Assert.Single(await f.Evaluate());Assert.Equal(RegulatoryApplicabilityOutcome.MANUAL_REVIEW,r.AutomatedOutcome);}
  [Fact] public async Task And_inside_group_and_or_between_groups_are_respected(){await using var f=await RegulatoryFixture.Create(tariff:"11111111",regime:"Temporal");var rule=f.Rule("R-1",RegulatoryRequirementStatus.VERIFIED,DocumentFieldCodes.TariffFraction,RegulatoryConditionOperator.EQUALS,"99999999");rule.Conditions.Add(new(){FieldCode="CUSTOMS_REGIME",Operator=RegulatoryConditionOperator.EQUALS,ExpectedValue="Definitivo",ConditionGroup="A",Sequence=2});rule.Conditions.Add(new(){FieldCode="CUSTOMS_REGIME",Operator=RegulatoryConditionOperator.EQUALS,ExpectedValue="Temporal",ConditionGroup="B",Sequence=1});await f.Save();Assert.Equal(RegulatoryApplicabilityOutcome.APPLIES,Assert.Single(await f.Evaluate()).AutomatedOutcome);}
  [Fact] public async Task Effective_version_is_selected_by_operation_date(){await using var f=await RegulatoryFixture.Create(tariff:"11111111",date:new(2026,2,1));f.Rule("R-VER",RegulatoryRequirementStatus.VERIFIED,DocumentFieldCodes.TariffFraction,RegulatoryConditionOperator.EQUALS,"11111111",version:1,from:new(2026,1,1),to:new(2026,6,30));f.Rule("R-VER",RegulatoryRequirementStatus.VERIFIED,DocumentFieldCodes.TariffFraction,RegulatoryConditionOperator.EQUALS,"99999999",version:2,from:new(2026,7,1));await f.Save();var r=Assert.Single(await f.Evaluate());Assert.Equal(1,r.RequirementVersion);Assert.Equal(RegulatoryApplicabilityOutcome.APPLIES,r.AutomatedOutcome);}
  [Fact] public async Task Verified_version_wins_over_newer_draft(){await using var f=await RegulatoryFixture.Create(tariff:"11111111");f.Rule("R-VER",RegulatoryRequirementStatus.VERIFIED,DocumentFieldCodes.TariffFraction,RegulatoryConditionOperator.EQUALS,"11111111",version:1);f.Rule("R-VER",RegulatoryRequirementStatus.DRAFT,DocumentFieldCodes.TariffFraction,RegulatoryConditionOperator.EQUALS,"11111111",version:2);await f.Save();var r=Assert.Single(await f.Evaluate());Assert.Equal(1,r.RequirementVersion);Assert.Equal(RegulatoryApplicabilityOutcome.APPLIES,r.AutomatedOutcome);}
  [Fact] public async Task Required_evidence_can_be_complete_partial_or_missing(){await using var f=await RegulatoryFixture.Create(tariff:"1");var rule=f.Rule("R-E",RegulatoryRequirementStatus.VERIFIED,DocumentFieldCodes.TariffFraction,RegulatoryConditionOperator.EQUALS,"1",evidence:"PERMISO_PREVIO");rule.EvidenceRequirements.Add(new(){DocumentTypeCode="NOM_EVIDENCE",EvidenceRole=RegulatoryEvidenceRole.SUPPORTING,IsRequired=true});f.Document("PERMISO_PREVIO");await f.Save();var r=Assert.Single(await f.Evaluate());Assert.Equal(RegulatoryEvidenceStatus.PARTIAL,r.EvidenceStatus);Assert.Contains(r.Evidence,x=>x.IsPresent);Assert.Contains(r.Evidence,x=>!x.IsPresent);}
  [Fact] public async Task Alternative_evidence_group_accepts_any_member(){await using var f=await RegulatoryFixture.Create(tariff:"1");var rule=f.Rule("R-ALT",RegulatoryRequirementStatus.VERIFIED,DocumentFieldCodes.TariffFraction,RegulatoryConditionOperator.EQUALS,"1");rule.EvidenceRequirements.AddRange(new RegulatoryEvidenceRequirement{DocumentTypeCode="NOM_EVIDENCE",EvidenceRole=RegulatoryEvidenceRole.ALTERNATIVE,IsRequired=true,AlternativeGroup="A"},new RegulatoryEvidenceRequirement{DocumentTypeCode="RRNA_OTHER",EvidenceRole=RegulatoryEvidenceRole.ALTERNATIVE,IsRequired=true,AlternativeGroup="A"});f.Document("RRNA_OTHER");await f.Save();Assert.Equal(RegulatoryEvidenceStatus.COMPLETE,Assert.Single(await f.Evaluate()).EvidenceStatus);}
  [Fact] public async Task Import_export_scope_is_enforced(){await using var f=await RegulatoryFixture.Create(tariff:"1",type:OperationType.Exportacion);var rule=f.Rule("R-I",RegulatoryRequirementStatus.VERIFIED,DocumentFieldCodes.TariffFraction,RegulatoryConditionOperator.EQUALS,"1");rule.OperationScope=RegulatoryOperationScope.IMPORT;await f.Save();Assert.Equal(RegulatoryApplicabilityOutcome.DOES_NOT_APPLY,Assert.Single(await f.Evaluate()).AutomatedOutcome);}
  [Fact] public async Task Tariff_and_nico_are_normalized_but_evaluated_separately(){await using var f=await RegulatoryFixture.Create(tariff:"85.04-40/01",nico:"07");f.Rule("R-T",RegulatoryRequirementStatus.VERIFIED,DocumentFieldCodes.TariffFraction,RegulatoryConditionOperator.EQUALS,"85044001");f.Rule("R-N",RegulatoryRequirementStatus.VERIFIED,DocumentFieldCodes.Nico,RegulatoryConditionOperator.EQUALS,"01");await f.Save();var r=await f.Evaluate();Assert.Equal(RegulatoryApplicabilityOutcome.APPLIES,r.Single(x=>x.RequirementCode=="R-T").AutomatedOutcome);Assert.Equal(RegulatoryApplicabilityOutcome.DOES_NOT_APPLY,r.Single(x=>x.RequirementCode=="R-N").AutomatedOutcome);}
  [Fact] public async Task Controlled_country_mapping_matches_iso_and_unknown_name_is_insufficient(){await using var f=await RegulatoryFixture.Create(origin:"México");f.Rule("R-MX",RegulatoryRequirementStatus.VERIFIED,DocumentFieldCodes.OriginCountry,RegulatoryConditionOperator.EQUALS,"MX");await f.Save();Assert.Equal(RegulatoryApplicabilityOutcome.APPLIES,Assert.Single(await f.Evaluate()).AutomatedOutcome);f.Operation.OriginCountry="País ambiguo";await f.Save();Assert.Equal(RegulatoryApplicabilityOutcome.INSUFFICIENT_DATA,Assert.Single(await f.Evaluate()).AutomatedOutcome);}
  [Fact] public async Task Evaluation_history_appends_and_manual_review_preserves_automatic_result(){await using var f=await RegulatoryFixture.Create(tariff:"1");f.Rule("R-H",RegulatoryRequirementStatus.VERIFIED,DocumentFieldCodes.TariffFraction,RegulatoryConditionOperator.EQUALS,"1");await f.Save();var first=Assert.Single(await f.Evaluate());await f.Evaluate();var reviewed=await f.Engine.ReviewAsync(f.Operation.Id,first.Id,RegulatoryManualOutcome.NEEDS_MORE_INFORMATION,"Validación sintética pendiente.",f.User.Id);Assert.Equal(RegulatoryApplicabilityOutcome.APPLIES,reviewed.AutomatedOutcome);Assert.Equal(RegulatoryManualOutcome.NEEDS_MORE_INFORMATION,reviewed.ManualOutcome);Assert.Equal(2,await f.Db.RegulatoryRequirementEvaluations.CountAsync());}
  [Fact] public async Task Regulatory_evaluation_does_not_mutate_legal_or_create_findings(){await using var f=await RegulatoryFixture.Create(tariff:"1");f.Rule("R-L",RegulatoryRequirementStatus.VERIFIED,DocumentFieldCodes.TariffFraction,RegulatoryConditionOperator.EQUALS,"1");var audit=new Audit{Number="LEGAL-KEEP",TradeOperation=f.Operation,AuditType=AuditType.Legal,Status=AuditStatus.Completed,CreatedBy=f.User.Id};f.Db.AuditResults.Add(new(){Audit=audit,RuleId="LEGAL-KEEP",Status=ResultStatus.Valid,Outcome=LegalOutcome.COMPLIANT,IsIncludedInLegalCompliance=true});await f.Save();await f.Evaluate();Assert.Equal(LegalOutcome.COMPLIANT,(await f.Db.AuditResults.SingleAsync()).Outcome);Assert.Empty(await f.Db.Findings.ToListAsync());}
  [Theory] [InlineData(RegulatoryConditionOperator.EQUALS,"Temporal",true)] [InlineData(RegulatoryConditionOperator.NOT_EQUALS,"Definitivo",true)] [InlineData(RegulatoryConditionOperator.IN,"Definitivo;Temporal",true)] [InlineData(RegulatoryConditionOperator.NOT_IN,"Definitivo|Depósito",true)] [InlineData(RegulatoryConditionOperator.PREFIX,"Temp",true)] [InlineData(RegulatoryConditionOperator.PRESENT,null,true)] [InlineData(RegulatoryConditionOperator.NOT_PRESENT,null,false)]
  public async Task Safe_string_operators_are_deterministic(RegulatoryConditionOperator op,string? expected,bool applies){await using var f=await RegulatoryFixture.Create(tariff:"1",regime:"Temporal");f.Rule("R-OP",RegulatoryRequirementStatus.VERIFIED,"CUSTOMS_REGIME",op,expected);await f.Save();Assert.Equal(applies?RegulatoryApplicabilityOutcome.APPLIES:RegulatoryApplicabilityOutcome.DOES_NOT_APPLY,Assert.Single(await f.Evaluate()).AutomatedOutcome);}
}

public class Sprint3ClassificationAndSecurityTests {
  [Theory] [InlineData("permiso_previo_demo.pdf","PERMISO_PREVIO")] [InlineData("aviso-automatico.pdf","AVISO_AUTOMATICO")] [InlineData("evidencia_cofepris.pdf","COFEPRIS_DOCUMENT")] [InlineData("constancia_semarnat.pdf","SEMARNAT_DOCUMENT")] [InlineData("documento_sedena.pdf","SEDENA_DOCUMENT")] [InlineData("certificado_fitosanitario.pdf","FITOSANITARIO_CERTIFICATE")] [InlineData("evidencia_nom-001.pdf","NOM_EVIDENCE")]
  public async Task Classifier_recognizes_regulatory_filename_signals(string name,string expected){var config=new ConfigurationBuilder().AddInMemoryCollection().Build();var classifier=new DocumentClassifier(null!,null!,config);var file=new FormFile(new MemoryStream([1]),0,1,"file",name){Headers=new HeaderDictionary(),ContentType="application/pdf"};Assert.Equal(expected,(await classifier.ClassifyAsync(file,CancellationToken.None)).DocumentTypeCode);}
  [Theory] [InlineData("GET","/api/regulatory-requirements")] [InlineData("GET","/api/regulatory-requirements/00000000-0000-0000-0000-000000000001")] [InlineData("POST","/api/regulatory-requirements")] [InlineData("PUT","/api/regulatory-requirements/00000000-0000-0000-0000-000000000001")] [InlineData("POST","/api/regulatory-requirements/00000000-0000-0000-0000-000000000001/version")] [InlineData("GET","/api/operations/00000000-0000-0000-0000-000000000001/regulatory-requirements")] [InlineData("POST","/api/operations/00000000-0000-0000-0000-000000000001/regulatory-requirements/evaluate")] [InlineData("GET","/api/operations/00000000-0000-0000-0000-000000000001/regulatory-requirements/history")] [InlineData("POST","/api/operations/00000000-0000-0000-0000-000000000001/regulatory-requirements/00000000-0000-0000-0000-000000000002/review")]
  public async Task Sprint3_endpoints_require_jwt(string method,string path){using var factory=new SaceFactory();var response=await factory.CreateClient().SendAsync(new HttpRequestMessage(new HttpMethod(method),path));Assert.Equal(HttpStatusCode.Unauthorized,response.StatusCode);}
  [Fact] public async Task Admin_api_creates_edits_and_versions_draft_without_directly_editing_verified(){using var factory=new SaceFactory();var client=await Authenticated(factory);var payload=new{code=$"DEMO-RRNA-API-{Guid.NewGuid():N}",name="Synthetic API rule",description="Synthetic test only",requirementCategory="OTHER",authorityCode="OTHER",authorityName=(string?)null,operationScope="BOTH",legalBasis=(string?)null,officialSourceUrl=(string?)null,publicationDate=(string?)null,effectiveFrom="2026-01-01T00:00:00Z",effectiveTo=(string?)null,isAutomatable=true,requiresManualReview=false,conditions=new[]{new{fieldCode="TARIFF_FRACTION",@operator="EQUALS",expectedValue="00000001",expectedValue2=(string?)null,conditionGroup="A",sequence=1}},evidenceRequirements=Array.Empty<object>()};var created=await client.PostAsJsonAsync("/api/regulatory-requirements",payload);Assert.Equal(HttpStatusCode.Created,created.StatusCode);using var createdJson=JsonDocument.Parse(await created.Content.ReadAsStringAsync());var id=createdJson.RootElement.GetProperty("id").GetGuid();Assert.Equal("DRAFT",createdJson.RootElement.GetProperty("status").GetString());var edited=await client.PutAsJsonAsync($"/api/regulatory-requirements/{id}",payload);Assert.True(edited.IsSuccessStatusCode,await edited.Content.ReadAsStringAsync());var versioned=await client.PostAsJsonAsync($"/api/regulatory-requirements/{id}/version",payload);Assert.Equal(HttpStatusCode.Created,versioned.StatusCode);using var versionJson=JsonDocument.Parse(await versioned.Content.ReadAsStringAsync());Assert.Equal(2,versionJson.RootElement.GetProperty("version").GetInt32());await using(var scope=factory.Services.CreateAsyncScope()){var db=scope.ServiceProvider.GetRequiredService<SaceDbContext>();var source=await db.RegulatoryRequirements.FindAsync(id);source!.Status=RegulatoryRequirementStatus.VERIFIED;await db.SaveChangesAsync();}var rejected=await client.PutAsJsonAsync($"/api/regulatory-requirements/{id}",payload);Assert.Equal(HttpStatusCode.BadRequest,rejected.StatusCode);Assert.Contains("VERIFIED_IMMUTABLE",await rejected.Content.ReadAsStringAsync());}
  static async Task<HttpClient> Authenticated(SaceFactory factory){var client=factory.CreateClient();var login=await client.PostAsJsonAsync("/api/auth/login",new{email="admin@sace.local",password="Admin123!"});login.EnsureSuccessStatusCode();using var json=JsonDocument.Parse(await login.Content.ReadAsStringAsync());client.DefaultRequestHeaders.Authorization=new AuthenticationHeaderValue("Bearer",json.RootElement.GetProperty("token").GetString());return client;}
}

public class Sprint3MigrationTests {
  const string Sprint2="20261016222705_CustomsValuationEngineV1";
  [Fact] public async Task Fresh_incremental_and_down_migration_are_scoped(){var directory=Path.Combine(Path.GetTempPath(),$"sace-sprint3-{Guid.NewGuid():N}");Directory.CreateDirectory(directory);var path=Path.Combine(directory,"validation.db");Guid userId,operationId,resultId;try{await using(var db=Context(path)){var migrator=db.Database.GetService<IMigrator>();await migrator.MigrateAsync(Sprint2);var user=new User{Name="Migration",Email="sprint3@example.invalid",PasswordHash="x"};var op=new TradeOperation{Folio="SPRINT3-MIG",PedimentoNumber="26",Period="2026-10",OperationDate=new(2026,10,1),TariffFraction="1"};var audit=new Audit{Number="LEGAL-S3",TradeOperation=op,AuditType=AuditType.Legal,Status=AuditStatus.Completed,CreatedBy=user.Id};var legal=new AuditResult{Audit=audit,RuleId="LEGAL-S3",Status=ResultStatus.Valid,Outcome=LegalOutcome.COMPLIANT,IsIncludedInLegalCompliance=true};db.AddRange(user,op,audit,legal);await db.SaveChangesAsync();userId=user.Id;operationId=op.Id;resultId=legal.Id;await migrator.MigrateAsync();Assert.Equal(5,await CountTables(db,"RegulatoryRequirements","RegulatoryRequirementConditions","RegulatoryEvidenceRequirements","RegulatoryRequirementEvaluations","RegulatoryRequirementEvaluationEvidence"));Assert.True(await IndexExists(db,"IX_RegulatoryRequirements_Code_Version"));await migrator.MigrateAsync(Sprint2);}await using(var db=Context(path)){Assert.Equal(0,await CountTables(db,"RegulatoryRequirements","RegulatoryRequirementConditions","RegulatoryEvidenceRequirements","RegulatoryRequirementEvaluations","RegulatoryRequirementEvaluationEvidence"));Assert.True(await db.Users.AnyAsync(x=>x.Id==userId));Assert.True(await db.TradeOperations.AnyAsync(x=>x.Id==operationId));Assert.Equal(LegalOutcome.COMPLIANT,(await db.AuditResults.SingleAsync(x=>x.Id==resultId)).Outcome);}}finally{SqliteConnection.ClearAllPools();if(Directory.Exists(directory))Directory.Delete(directory,true);}}
  static SaceDbContext Context(string path)=>new(new DbContextOptionsBuilder<SaceDbContext>().UseSqlite($"Data Source={path}").Options);
  static async Task<long> CountTables(SaceDbContext db,params string[] names){var connection=(SqliteConnection)db.Database.GetDbConnection();if(connection.State!=System.Data.ConnectionState.Open)await connection.OpenAsync();await using var command=connection.CreateCommand();command.CommandText=$"SELECT COUNT(*) FROM sqlite_master WHERE type='table' AND name IN ({string.Join(',',names.Select((_,i)=>$"$n{i}"))})";for(var i=0;i<names.Length;i++)command.Parameters.AddWithValue($"$n{i}",names[i]);return Convert.ToInt64(await command.ExecuteScalarAsync());}
  static async Task<bool> IndexExists(SaceDbContext db,string name){var connection=(SqliteConnection)db.Database.GetDbConnection();if(connection.State!=System.Data.ConnectionState.Open)await connection.OpenAsync();await using var command=connection.CreateCommand();command.CommandText="SELECT COUNT(*) FROM sqlite_master WHERE type='index' AND name=$name";command.Parameters.AddWithValue("$name",name);return Convert.ToInt64(await command.ExecuteScalarAsync())==1;}
}

public sealed class RegulatoryFixture:IAsyncDisposable {
  readonly SqliteConnection connection;public SaceDbContext Db{get;}public User User{get;}public TradeOperation Operation{get;}public RegulatoryRequirementEngine Engine{get;}
  RegulatoryFixture(SqliteConnection connection,SaceDbContext db,User user,TradeOperation operation){this.connection=connection;Db=db;User=user;Operation=operation;Engine=new(db);}
  public static async Task<RegulatoryFixture> Create(string tariff="",string? nico=null,DateTime? date=null,string? description=null,string regime="Definitivo",string origin="MX",OperationType type=OperationType.Importacion){var connection=new SqliteConnection("DataSource=:memory:");await connection.OpenAsync();var db=new SaceDbContext(new DbContextOptionsBuilder<SaceDbContext>().UseSqlite(connection).Options);await db.Database.EnsureCreatedAsync();var user=new User{Name="Sprint 3",Email=$"{Guid.NewGuid():N}@example.invalid",PasswordHash="x"};var operation=new TradeOperation{Folio=$"RRNA-{Guid.NewGuid():N}",PedimentoNumber="26",Period="2026-01",OperationDate=DateTime.SpecifyKind(date??new DateTime(2026,1,15),DateTimeKind.Utc),TariffFraction=tariff,Nico=nico,GoodsDescription=description,CustomsRegime=regime,OriginCountry=origin,DestinationCountry="US",OperationType=type};db.AddRange(user,operation);await db.SaveChangesAsync();return new(connection,db,user,operation);}
  public RegulatoryRequirement Rule(string code,RegulatoryRequirementStatus status,string field,RegulatoryConditionOperator op,string? expected,int version=1,DateTime? from=null,DateTime? to=null,string? evidence=null){var rule=new RegulatoryRequirement{Code=code,Version=version,Name=code,Description="Synthetic test only",Status=status,RequirementCategory=RequirementCategory.OTHER,OperationScope=RegulatoryOperationScope.BOTH,EffectiveFrom=from,EffectiveTo=to,Conditions=[new(){FieldCode=field,Operator=op,ExpectedValue=expected,ConditionGroup="A",Sequence=1}]};if(evidence is not null)rule.EvidenceRequirements.Add(new(){DocumentTypeCode=evidence,EvidenceRole=RegulatoryEvidenceRole.PRIMARY,IsRequired=true});Db.RegulatoryRequirements.Add(rule);return rule;}
  public OperationDocument Document(string code){var type=Db.DocumentTypes.Local.FirstOrDefault(x=>x.Code==code)??new DocumentType{Code=code,Name=code};var doc=new OperationDocument{TradeOperation=Operation,DocumentType=type,OriginalFileName=$"{code}.pdf",StoredFileName=$"{code}.pdf",MimeType="application/pdf",Extension=".pdf",FileSize=1,FilePath=$"synthetic/{code}.pdf",UploadedBy=User.Id,ValidationStatus=ValidationStatus.Valid};Db.OperationDocuments.Add(doc);return doc;}
  public Task Save()=>Db.SaveChangesAsync();public Task<IReadOnlyList<RegulatoryRequirementEvaluation>> Evaluate()=>Engine.EvaluateAsync(Operation.Id,null,User.Id);
  public async ValueTask DisposeAsync(){await Db.DisposeAsync();await connection.DisposeAsync();}
}
